/**
 * The two fields a project really needs — name and outcome — plus the two
 * the server requires but the operator should not have to look up: the key
 * prefix (derived from the name until they edit it) and the lead (the signed-
 * in user until they change it). Everything else the design's charter
 * captures lives behind `charter-detail-fields.tsx`'s disclosure
 * (`docs/toolu/specs/2026-09-20-agent-native-project-management-design.md`
 * § Console information architecture).
 *
 * Every field here is a `form.Field` on the parent's own form instance, so
 * the names are checked against `CharterFormSchema` and the notes under the
 * controls are the schema's own messages.
 */

import { SchemaTextareaField, SchemaTextField } from '@/ui/components/schema-fields';

import {
  CHARTER_KEY_PREFIX_MAX,
  CHARTER_NAME_MAX,
  CHARTER_OUTCOME_MAX,
  deriveKeyPrefix,
} from './charter-form-rules';
import type { CharterForm } from './use-charter-form';

/** How the lead is chosen — the session's user, or an id the operator typed. */
type LeadFieldState = {
  /** How to name the signed-in user; `undefined` until the session is read. */
  sessionLabel: string | undefined;
  /** True once the operator chose to type an id instead of keeping themselves. */
  overriding: boolean;
  onOverride: () => void;
  onRestoreSelf: () => void;
};

/** Props for `CharterEssentialsFields`. */
type CharterEssentialsFieldsProps = {
  form: CharterForm;
  lead: LeadFieldState;
  /** False once the operator edits the prefix — the name stops filling it then. */
  keyPrefixAuto: boolean;
  onKeyPrefixEdited: () => void;
};

/** The lead as a fact the operator can change, rather than an id they must find. */
function CharterLeadField({ form, lead }: { form: CharterForm; lead: LeadFieldState }) {
  if (lead.sessionLabel !== undefined && !lead.overriding) {
    return (
      <div className="flex flex-col gap-1">
        <span className="type-label text-ink-muted">lead</span>
        <div className="h-field-app flex items-center justify-between gap-3 rounded-sm border border-border bg-surface-inset px-3">
          <span className="type-body-sm truncate text-ink">{lead.sessionLabel} · you</span>
          <button
            type="button"
            onClick={lead.onOverride}
            className="type-button transition-hover flex-none text-ink-muted"
          >
            Change
          </button>
        </div>
        <p className="type-meta text-ink-muted">Whoever owns this charter's decisions.</p>
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-1">
      <form.Field name="leadUserId">
        {(field) => (
          <SchemaTextField
            field={field}
            label="lead (workspace member id)"
            fieldId="charter-lead"
            aria-required
          />
        )}
      </form.Field>
      {lead.sessionLabel !== undefined && (
        <button
          type="button"
          onClick={lead.onRestoreSelf}
          className="type-button transition-hover self-start text-ink-muted"
        >
          Lead it myself
        </button>
      )}
    </div>
  );
}

/** Name, outcome, key prefix, lead — the only fields on screen before the disclosure. */
export function CharterEssentialsFields({
  form,
  lead,
  keyPrefixAuto,
  onKeyPrefixEdited,
}: CharterEssentialsFieldsProps) {
  return (
    <div className="flex flex-col gap-4">
      <form.Field name="name">
        {(field) => (
          <SchemaTextField
            field={field}
            label="name"
            fieldId="charter-name"
            aria-required
            maxLength={CHARTER_NAME_MAX}
            onChange={(event) => {
              field.handleChange(event.target.value);
              if (keyPrefixAuto) {
                form.setFieldValue('keyPrefix', deriveKeyPrefix(event.target.value));
              }
            }}
          />
        )}
      </form.Field>
      <form.Field name="outcome">
        {(field) => (
          <SchemaTextareaField
            field={field}
            label="outcome"
            fieldId="charter-outcome"
            aria-required
            maxLength={CHARTER_OUTCOME_MAX}
            hint="What is true once this project is done — one or two sentences."
          />
        )}
      </form.Field>
      <div className="grid gap-4 lg:grid-cols-2">
        <form.Field name="keyPrefix">
          {(field) => (
            <SchemaTextField
              field={field}
              label="key prefix"
              fieldId="charter-key-prefix"
              aria-required
              maxLength={CHARTER_KEY_PREFIX_MAX}
              hint={
                keyPrefixAuto
                  ? 'Derived from the name — type to override.'
                  : 'Uppercase letters/digits, starting with a letter.'
              }
              onChange={(event) => {
                onKeyPrefixEdited();
                field.handleChange(event.target.value.toUpperCase());
              }}
            />
          )}
        </form.Field>
        <CharterLeadField form={form} lead={lead} />
      </div>
    </div>
  );
}
